def summary():
    passed = sum(1 for _, ok in VERDICTS if ok)
    total = len(VERDICTS)
    print("\n" + "=" * 64)
    print(f" ZOO CLOSED | {passed}/{total} verifications PASS | "
          f"{total - passed} FAIL | {total} checks total")
    print("=" * 64)


